{
  "reviewed_collab_notes": true,
  "recommendation_summary": "Which path to choose depends on signs of compromise and urgency. If you have any indication that credentials/tokens were exposed or there is unauthorized activity, escalate to Security now for a coordinated full export and key rotation. If this is purely investigative/debugging with no signs of compromise, start with redacted logs and a concise timeline and only escalate if suspicious items appear.",
  "decision_guidelines": [
    {
      "when_to_escalate_to_security_now": [
        "You observed unauthorized access, unknown IPs, or anomalous activity.",
        "You have reason to believe tokens/credentials were leaked or used externally.",
        "Regulatory/legal or compliance obligations require a full forensic export.",
        "You want coordinated key rotation and revocation handled by Security."
      ]
    },
    {
      "when_redacted_logs_and_timeline_are_sufficient": [
        "You need operational troubleshooting (delivery failures, webhook debugging) and there are no signs of compromise.",
        "You want a readable summary for debugging or internal review without exposing secrets.",
        "You prefer to limit exposure of sensitive data while we investigate further."
      ]
    }
  ],
  "immediate_recommended_actions_you_can_take_right_away": [
    "Rotate any keys/tokens you control that you suspect may be exposed (do this immediately if compromise suspected).",
    "Revoke/replace webhook secrets and update consumers to use the new secret.",
    "Restrict access (IP allowlists, temporary credential disablement) where feasible.",
    "Enable additional logging/alerting and check recent activity for suspicious patterns.",
    "Inform your security/compliance team if you suspect a breach so they can be ready for escalation."
  ],
  "if_you_choose_redacted_logs_and_timeline (my offer and timeline)": {
    "what_i_will_provide": [
      "Redacted log excerpts or full export with sensitive fields (tokens, secrets, PII) masked.",
      "A concise timeline of relevant events (timestamps, request IDs, status codes, source IPs where appropriate).",
      "Indicators of compromise (IOCs) extracted from logs, with sensitive values redacted."
    ],
    "formats_available": ["CSV", "JSON", "PDF"],
    "time_to_deliver": "Typically 6–24 hours after you confirm the time window and format.",
    "what_i_need_from_you": [
      "Time window (start and end UTC timestamps).",
      "Event types (e.g., webhook deliveries, auth failures, token usage).",
      "Preferred format for the export (CSV/JSON/PDF)."
    ]
  },
  "if_you_choose_to_escalate_to_security (my offer and timeline)": {
    "what_i_will_do": [
      "Initiate a documented security escalation requesting a full, auditable forensic export and, if needed, coordinated admin key rotation.",
      "Preserve all logs and audit trails intact and include them in the security handoff (we will not delete evidence)."
    ],
    "what_security_may_do": [
      "Review the raw logs and tokens under an established process, produce a forensic report, and perform or authorize admin API key resets if required.",
      "Coordinate any customer-facing communications and remediation steps to meet compliance requirements."
    ],
    "typical_response_time": "Security response usually 24–72 hours depending on severity and queue, but urgent cases are prioritized.",
    "what_i_need_from_you": [
      "Explicit confirmation you want me to open the security escalation.",
      "Any specific keys/tokens, systems, or time ranges you suspect are affected."
    ]
  },
  "risks_and_policy_constraints (what I will not do)": [
    "I will not share raw logs containing unredacted credentials or token dumps.",
    "I will not delete or alter customer-visible logs or internal audit trails.",
    "I will not reset admin API keys without explicit written authorization from the security team.",
    "I will not mark the ticket resolved until you confirm the issue is fixed."
  ],
  "recommended_next_step_for_most_cases": "If you are unsure whether compromise occurred: request redacted logs and a timeline for the last 24–72 hours now. If anything suspicious appears in that output, we should escalate immediately. If you already suspect compromise, request escalation to Security now.",
  "what_i_need_from_you_to_proceed": [
    "Choose one: (A) Prepare redacted logs/timeline, or (B) Escalate to Security for full export and key rotation.",
    "If A: provide time window (start/end UTC) and preferred format (CSV/JSON/PDF) and the event types to include.",
    "If B: explicitly confirm you want me to open the security escalation and list any suspected tokens/keys/systems and time ranges."
  ],
  "offer": "Tell me which option you prefer and provide the requested details; I will take the next step immediately (prepare redacted output or open a security escalation)."
}

